        Element(19, "K", "پتاسیم", "Potassium", 39.098, 4, 1, "s", ElementCategory.AlkaliMetal, "[Ar] 4s¹", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• فلز قلیایی دوره ۴ با واکنش شدیدتر و انفجاری‌تر از سدیم با آب.\n• رنگ شعله: بنفش کم‌رنگ / ارغوانی.\n• کاتیون اصلی مایع درون‌سلولی بدن؛ تنظیم ضربان قلب، انقباض عضلانی و انتقال پیام عصبی.\n• کودهای شیمیایی پتاسیم (پتاس، KCl و K₂SO₄) جهت افزایش مقاومت گیاهان به بیماری و خشکی."),
        Element(20, "Ca", "کلسیم", "Calcium", 40.078, 4, 2, "s", ElementCategory.AlkalineEarth, "[Ar] 4s²", null, null, null, null, ElementState.Solid, 2, "", "نکات طلایی کنکور:\n• رنگ شعله: سرخ آجری مشخص.\n• فراوان‌ترین عنصر فلزی در بدن انسان؛ جزء اصلی استخوان‌ها، دندان‌ها و پوسته تخم‌مرغ.\n• ترکیبات کلیدی در کنکور:\n  - سنگ آهک CaCO₃ (تجزیه گرمایی به آهک زنده CaO و CO₂).\n  - آهک مرده Ca(OH)₂ (آب آهک برای شناسایی گاز CO₂ با تشکیل رسوب شیری).\n  - گچ CaSO₄.2H₂O هیدراته و گچ پخته."),
        Element(21, "Sc", "اسکاندیم", "Scandium", 44.956, 4, 3, "d", ElementCategory.TransitionMetal, "[Ar] 3d¹ 4s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• نخستین فلز واسطه جدول تناوبی در دوره ۴ گروه ۳.\n• تنها عدد اکسایش پایدار آن +۳ است (کاتیون Sc³⁺).\n• یون Sc³⁺ دارای آرایش [Ar] 3d⁰ بوده و فاقد الکترون d است، لذا بی‌رنگ و دیامغناطیس است (استثنای رنگین بودن یون‌های فلزات واسطه!).\n• آلیاژ آلومینیم-اسکاندیم با استحکام بالا در بدنه جنگنده‌ها و فریم‌های هوافضا."),
        Element(22, "Ti", "تیتانیم", "Titanium", 47.867, 4, 4, "d", ElementCategory.TransitionMetal, "[Ar] 3d² 4s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• فلز سبک با استحکام برابر فولاد و مقاومت بی‌نظیر به خوردگی شیمیایی و آب دریا.\n• زیست‌سازگاری عالی در ایمپلنت‌های ارتوپدی و مفاصل مصنوعی.\n• تیتانیم دی‌اکسید (TiO₂): سفیدترین رنگدانه جهان (تیتان سفید) در رنگ‌های ساختمانی، کاغذ، پلاستیک و کرم‌های ضدآفتاب به عنوان جاذب فرابنفش."),
        Element(23, "V", "وانادیم", "Vanadium", 50.942, 4, 5, "d", ElementCategory.TransitionMetal, "[Ar] 3d³ 4s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• تنوع چشمگیر اکسایش از +۲ تا +۵ با رنگ‌های زیبا: V²⁺ (بنفش)، V³⁺ (سبز)، VO²⁺ (آبی)، VO₂⁺ (زرد).\n• کاتالیزور دی‌وانادیم پنتاکسید (V₂O₅) در فرآیند تماسی اکسایش SO₂ به SO₃ برای سنتز اسید سولفوریک.\n• آلیاژ فرووانادیم در فولاد فنر خودرو و ابزارهای برشی پرسرعت."),
        Element(24, "Cr", "کروم", "Chromium", 51.996, 4, 6, "d", ElementCategory.TransitionMetal, "[Ar] 3d⁵ 4s¹", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• استثنای بسیار مهم آرایش الکترونی: [Ar] 3d⁵ 4s¹ (نیمه‌پر با ۶ الکترون تک، بیشترین تعداد الکترون تک در دوره ۴!).\n• روکش آبکاری کروم بسیار براق و مقاوم در برابر زنگ‌زدگی.\n• جزء کلیدی فولاد زنگ‌نزن استیل (حداقل ۱۰.۵٪ کروم).\n• کرومات (CrO₄²⁻، زرد) و دی‌کرومات (Cr₂O₇²⁻، نارنجی) به عنوان اکسنده‌های قوی محیط اسیدی."),
        Element(25, "Mn", "منگنز", "Manganese", 54.938, 4, 7, "d", ElementCategory.TransitionMetal, "[Ar] 3d⁵ 4s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• وسیع‌ترین بازه اعداد اکسایش در دوره ۴ (از +۲ تا +۷، با ۷ الکترون ظرفیت).\n• پتاسیم پرمنگنات KMnO₄: بلورهای بنفش تیره و قوی‌ترین اکسنده در محیط اسیدی (احیا به کاتیون بی‌رنگ یا کم‌رنگ Mn²⁺).\n• منگنز دی‌اکسید MnO₂: پودر سیاه کاتالیزور تجزیه هیدروژن پراکسید (آب‌اکسیژنه) و کاتد باتری‌های خشک روی-کربن."),
        Element(26, "Fe", "آهن", "Iron", 55.845, 4, 8, "d", ElementCategory.TransitionMetal, "[Ar] 3d⁶ 4s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• پرکاربردترین فلز جهان (بیش از ۹۰٪ تولید کل فلزات).\n• استخراج در کوره بلند با واکنش Fe₂O₃، کک و CO در دماهای مختلف.\n• زنگ زدن: فرآیند الکتروشیمیایی نیازمند هم‌زمان آب و اکسیژن و تولید Fe(OH)₃ قهوه‌ای متخلخل.\n• Fe²⁺ سبز کم‌رنگ و Fe³⁺ زرد/قهوه‌ای؛ کاتیون Fe²⁺ در مرکز هموگلوبین برای انتقال اکسیژن خون."),
        Element(27, "Co", "کبالت", "Cobalt", 58.933, 4, 9, "d", ElementCategory.TransitionMetal, "[Ar] 3d⁷ 4s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• عنصر فرومغناطیس؛ آهنرباهای قوی آلنیکو (Al-Ni-Co).\n• هسته مرکزی ویتامین B₁₂ برای خونسازی و سلامت مغز.\n• رنگ آبی لاجوردی عمیق در صنایع کاشی، لعاب و شیشه‌گری سنتی.\n• رادیوایزوتوپ کبالت-۶۰ (⁶⁰Co): چشمه پرتوهای گاما برای پرتودرمانی سرطان و استریل لوازم پزشکی."),
        Element(28, "Ni", "نیکل", "Nickel", 58.693, 4, 10, "d", ElementCategory.TransitionMetal, "[Ar] 3d⁸ 4s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• کاتالیزور فرآیند هیدروژناسیون پیوندهای دوگانه در هیدروکربن‌ها و تبدیل روغن مایع به جامد.\n• آلیاژ فولاد ضدزنگ و المنت‌های حرارتی نیکل-کروم.\n• باتری‌های قابل شارژ نیکل-کادمیم و نیکل-متال هیدرید."),
        Element(29, "Cu", "مس", "Copper", 63.546, 4, 11, "d", ElementCategory.TransitionMetal, "[Ar] 3d¹⁰ 4s¹", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• استثنای بسیار مهم آرایش الکترونی: [Ar] 3d¹⁰ 4s¹ (زیرلایه d پر و پایدار با یک الکترون تک در 4s).\n• فلز سرخ با دومین رسانایی الکتریکی و گرمایی بالا بعد از نقره.\n• زنگ مس (پاتین): کربنات بازی مس CuCO₃.Cu(OH)₂ سبز رنگ روی گنبدهای مسی.\n• کاتیون Cu²⁺ در آب آبی‌رنگ است (کات‌کبود CuSO₄.5H₂O).\n• رنگ شعله: سبز زمردی / آبی درخشان؛ حل شدن در اسید نیتریک HNO₃ غلیظ با تولید گاز قهوه‌ای NO₂."),
        Element(30, "Zn", "روی", "Zinc", 65.38, 4, 12, "d", ElementCategory.TransitionMetal, "[Ar] 3d¹⁰ 4s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• پایان زیرلایه 3d؛ تنها دارای عدد اکسایش +۲ (کاتیون Zn²⁺ با آرایش [Ar] 3d¹⁰).\n• کاتیون Zn²⁺ بی‌رنگ و دیامغناطیس است.\n• آهن گالوانیزه (آهن سفید): روکش فداشونده روی با پتانسیل منفی‌تر (Zn = -0.76 V در برابر Fe = -0.44 V) که حتی در صورت خراش، روی فدا می‌شود.\n• آلیاژ برنج (مس و روی) و پماد زینک اکساید ZnO."),
        Element(31, "Ga", "گالیم", "Gallium", 69.723, 4, 13, "p", ElementCategory.PostTransitionMetal, "[Ar] 3d¹⁰ 4s² 4p¹", null, null, null, null, ElementState.Solid, 3, "", "نکات طلایی کنکور:\n• فلز با دمای ذوب ۲۹.۸°C (در کف دست انسان ذوب می‌شود!).\n• اکا-آلومینیم مندلیف با تطابق شگفت‌انگیز خواص پیش‌بینی‌شده.\n• ترکیب گالیم آرسنید (GaAs) در دیودهای نورافشان لیزری و LEDهای پرسرعت."),
        Element(32, "Ge", "ژرمانیم", "Germanium", 72.63, 4, 14, "p", ElementCategory.Metalloid, "[Ar] 3d¹⁰ 4s² 4p²", null, null, null, null, ElementState.Solid, 4, "", "نکات طلایی کنکور:\n• اکا-سیلیسیم مندلیف؛ شبه‌فلز در ساخت ترانزیستورهای اولیه تاریخ الکترونیک.\n• فیبرهای نوری، عدسی‌های مادون قرمز دید در شب و طیف‌سنج‌ها."),
        Element(33, "As", "آرسنیک", "Arsenic", 74.922, 4, 15, "p", ElementCategory.Metalloid, "[Ar] 3d¹⁰ 4s² 4p³", null, null, null, null, ElementState.Solid, 5, "", "نکات طلایی کنکور:\n• شبه‌فلز بسیار سمی؛ مهارکننده تنفس سلولی و تولید ATP با اتصال به آنزیم‌ها.\n• کاربرد تاریخی در سموم دفع آفات و آلیاژکننده صفحات سربی باتری خودرو."),
        Element(34, "Se", "سلنیم", "Selenium", 78.971, 4, 16, "p", ElementCategory.ReactiveNonmetal, "[Ar] 3d¹⁰ 4s² 4p⁴", null, null, null, null, ElementState.Solid, 6, "", "نکات طلایی کنکور:\n• ویژگی فوتوالکتریک نوری: با تابش نور، رسانایی الکتریکی آن چندین برابر می‌شود؛ درام دستگاه‌های فتوکپی و سنسورهای نورسنج.\n• آنتی‌اکسیدان ضروری در آنزیم گلوتاتیون پراکسیداز بدن انسان."),
        Element(35, "Br", "برم", "Bromine", 79.904, 4, 17, "p", ElementCategory.Halogen, "[Ar] 3d¹⁰ 4s² 4p⁵", null, null, null, null, ElementState.Liquid, 7, "", "نکات طلایی کنکور:\n• تنها نافلز مایع در دمای اتاق؛ مایع قرمز-قهوه‌ای تیره و فرّار با بخارات خفه‌کننده.\n• تست آب برم: شناسایی پیوندهای دوگانه و سه‌گانه آلکن‌ها و آلکین‌ها با بی‌رنگ شدن محلول برم.\n• نمک حساس به نور AgBr در فیلم‌های عکاسی سنتی."),
        Element(36, "Kr", "کریپتون", "Krypton", 83.798, 4, 18, "p", ElementCategory.NobleGas, "[Ar] 3d¹⁰ 4s² 4p⁶", null, null, null, null, ElementState.Gas, 8, "", "نکات طلایی کنکور:\n• پایان دوره ۴ جدول با آرایش هشت‌تایی گاز نجیب.\n• لامپ‌های فلاش عکاسی پرسرعت، چراغ‌های هشدار باند فرودگاه و لیزرهای جراحی قرنیه چشم."),
        Element(37, "Rb", "روبیدیم", "Rubidium", 85.468, 5, 1, "s", ElementCategory.AlkaliMetal, "[Kr] 5s¹", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• فلز قلیایی دوره ۵ با واکنش انفجاری با آب؛ رنگ شعله سرخ مایل به بنفش.\n• ساعت‌های اتمی دقیق و حسگرهای فوتوالکتریک نوری."),
        Element(38, "Sr", "استرانسیم", "Strontium", 87.62, 5, 2, "s", ElementCategory.AlkalineEarth, "[Kr] 5s²", null, null, null, null, ElementState.Solid, 2, "", "نکات طلایی کنکور:\n• فلز قلیایی خاکی؛ رنگ شعله سرخ درخشان در منورها و وسایل آتش‌بازی.\n• شباهت رفتاری به کلسیم در جذب استخوانی (استرانسیم-۹۰ حاصل از انفجار اتمی)."),
        Element(39, "Y", "ایتریم", "Yttrium", 88.906, 5, 3, "d", ElementCategory.TransitionMetal, "[Kr] 4d¹ 5s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• فلز واسطه؛ در ساخت ابررساناهای دمای بالا (YBCO) و فسفرهای قرمز لامپ‌های تصویری."),
        Element(40, "Zr", "زیرکونیم", "Zirconium", 91.224, 5, 4, "d", ElementCategory.TransitionMetal, "[Kr] 4d² 5s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• روکش غلاف میله‌های سوخت هسته‌ای اورانیم به دلیل جذب بسیار پایین نوترون و مقاومت گرمایی بالا."),
        Element(41, "Nb", "نیوبیم", "Niobium", 92.906, 5, 5, "d", ElementCategory.TransitionMetal, "[Kr] 4d⁴ 5s¹", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• آلیاژهای ابررسانای آهنرباهای MRI و بدنه موتورهای جت و موشک‌های هوافضا."),
        Element(42, "Mo", "مولیبدن", "Molybdenum", 95.95, 5, 6, "d", ElementCategory.TransitionMetal, "[Kr] 4d⁵ 5s¹", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• استثنای آرایش الکترونی: [Kr] 4d⁵ 5s¹؛ افزایش مقاومت کششی و حرارتی فولادها و کوآنزیم آنزیم نیتروژناز تثبیت نیتروژن."),
        Element(43, "Tc", "تکنسیم", "Technetium", 98.0, 5, 7, "d", ElementCategory.TransitionMetal, "[Kr] 4d⁵ 5s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• نخستین عنصر مصنوعی ساخته دست بشر؛ فاقد ایزوتوپ پایدار.\n• ایزوتوپ Tc-99m پرمصرف‌ترین رادیوداروی پزشکی هسته‌ای در تصویربرداری غده تیروئید و استخوان."),
        Element(44, "Ru", "روتنیم", "Ruthenium", 101.07, 5, 8, "d", ElementCategory.TransitionMetal, "[Kr] 4d⁷ 5s¹", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• از فلزات نجیب گروه پلاتین؛ پوشش الکترودهای تیتانیمی در فرآیند صنعتی کلر-آلکالی."),
        Element(45, "Rh", "رودیم", "Rhodium", 102.91, 5, 9, "d", ElementCategory.TransitionMetal, "[Kr] 4d⁸ 5s¹", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• فلز فوق‌العاده گران‌بها و کمیاب؛ کاتالیزور اصلی سه منظوره در مبدل کاتالیستی خودروهای بنزینی برای حذف CO و NO."),
        Element(46, "Pd", "پالادیم", "Palladium", 106.42, 5, 10, "d", ElementCategory.TransitionMetal, "[Kr] 4d¹⁰", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• استثنای عجیب آرایش الکترونی: [Kr] 4d¹⁰ (زیرلایه 5s خالی است!).\n• قابلیت جذب گاز هیدروژن تا ۹۰۰ برابر حجم خود؛ کاتالیزور هیدروژناسیون صنعتی."),
        Element(47, "Ag", "نقره", "Silver", 107.87, 5, 11, "d", ElementCategory.TransitionMetal, "[Kr] 4d¹⁰ 5s¹", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• استثنای آرایش: [Kr] 4d¹⁰ 5s¹؛ بالاترین رسانایی الکتریکی و گرمایی در بین تمام عناصر جدول!\n• رسوب‌های نقره در کنکور: AgCl (سفید)، AgBr (زرد کم‌رنگ)، AgI (زرد پررنگ).\n• باتری دکمه‌ای روی-نقره (Zn + Ag₂O → ZnO + 2Ag) با ولتاژ پایدار ۱.۶ ولت."),
        Element(48, "Cd", "کادمیم", "Cadmium", 112.41, 5, 12, "d", ElementCategory.TransitionMetal, "[Kr] 4d¹⁰ 5s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• فلز سمی؛ میله‌های کنترل جذب نوترون در راکتورهای اتمی؛ باتری‌های قابل شارژ نیکل-کادمیم."),
        Element(49, "In", "اندیم", "Indium", 114.82, 5, 13, "p", ElementCategory.PostTransitionMetal, "[Kr] 4d¹⁰ 5s² 5p¹", null, null, null, null, ElementState.Solid, 3, "", "نکات طلایی کنکور:\n• ترکیب اکسید قلع-اندیم (ITO) به عنوان لایه رسانای شفاف در نمایشگرهای لمسی گوشی‌های هوشمند."),
        Element(50, "Sn", "قلع", "Tin", 118.71, 5, 14, "p", ElementCategory.PostTransitionMetal, "[Kr] 4d¹⁰ 5s² 5p²", null, null, null, null, ElementState.Solid, 4, "", "نکات طلایی کنکور:\n• فلز گروه ۱۴؛ روکش ورق حلبی قوطی‌های کنسرو برای جلوگیری از زنگ زدن آهن؛ آلیاژ برنز با مس؛ لحیم‌کاری."),
        Element(51, "Sb", "آنتیموان", "Antimony", 121.76, 5, 15, "p", ElementCategory.Metalloid, "[Kr] 4d¹⁰ 5s² 5p³", null, null, null, null, ElementState.Solid, 5, "", "نکات طلایی کنکور:\n• شبه‌فلز؛ افزایش سختی سرب در صفحات باتری خودرو و مواد ضدحریق نسوز."),
        Element(52, "Te", "تلوریم", "Tellurium", 127.6, 5, 16, "p", ElementCategory.Metalloid, "[Kr] 4d¹⁰ 5s² 5p⁴", null, null, null, null, ElementState.Solid, 6, "", "نکات طلایی کنکور:\n• شبه‌فلز در سلول‌های خورشیدی کادمیم تلورید و شیشه‌های الکتروکرومیک هوشمند."),
        Element(53, "I", "ید", "Iodine", 126.9, 5, 17, "p", ElementCategory.Halogen, "[Kr] 4d¹⁰ 5s² 5p⁵", null, null, null, null, ElementState.Solid, 7, "", "نکات طلایی کنکور:\n• هالوژن جامد بنفش-سیاه که در اثر گرما مستقیماً تصعید (فرازش) شده و بخارات ارغوانی تولید می‌کند.\n• معرف شناسایی نشاسته با ایجاد رنگ آبی تیره شاخص.\n• جزء ساختار هورمون تیروکسین برای پیشگیری از گواتر (نمک تصفیه‌شده یددار)."),
        Element(54, "Xe", "زنون", "Xenon", 131.29, 5, 18, "p", ElementCategory.NobleGas, "[Kr] 4d¹⁰ 5s² 5p⁶", null, null, null, null, ElementState.Gas, 8, "", "نکات طلایی کنکور:\n• گاز نجیب سنگین؛ نخستین گاز نجیبی که نیل بارتلت با آن ترکیب ساخت (XePtF₆).\n• سوخت موتورهای پیشرانش یونی فضاپیماهای دوردست؛ لامپ‌های روشنایی زنون اتومبیل."),
        Element(55, "Cs", "سزیم", "Caesium", 132.91, 6, 1, "s", ElementCategory.AlkaliMetal, "[Xe] 6s¹", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• کمترین الکترونگاتیوی (۰.۷۹) و بزرگ‌ترین شعاع اتمی در میان عناصر پایدار جدول تناوبی.\n• دمای ذوب بسیار پایین ۲۸.۴°C؛ تعریف استاندارد بین‌المللی یک ثانیه بر اساس نوسانات اتم سزیم-۱۳۳."),
        Element(56, "Ba", "باریم", "Barium", 137.33, 6, 2, "s", ElementCategory.AlkalineEarth, "[Xe] 6s²", null, null, null, null, ElementState.Solid, 2, "", "نکات طلایی کنکور:\n• فلز قلیایی خاکی دوره ۶؛ رنگ شعله سبز سیبی مشخص.\n• باریم سولفات BaSO₄ نامحلول در آب و کدر در برابر اشعه X؛ سوسپانسیون بلع باریم جهت عکس‌برداری رادیولوژی دستگاه گوارش."),
        Element(57, "La", "لانتان", "Lanthanum", 138.91, 6, 3, "f", ElementCategory.Lanthanide, "[Xe] 5d¹ 6s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• سرگروه لانتانیدها؛ الکترود باتری‌های نیکل-متال هیدرید خودروهای هیبریدی."),
        Element(58, "Ce", "سریم", "Cerium", 140.12, 6, 4, "f", ElementCategory.Lanthanide, "[Xe] 4f¹ 5d¹ 6s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• فراوان‌ترین عنصر نادر خاکی؛ پولیش عدسی‌های اپتیکی و سنگ آتش‌زنه فندک."),
        Element(59, "Pr", "پرازئودیمیم", "Praseodymium", 140.91, 6, 5, "f", ElementCategory.Lanthanide, "[Xe] 4f³ 6s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• آلیاژ آهنربای دائمی و عینک‌های محافظ جوشکاری."),
        Element(60, "Nd", "نئودیمیم", "Neodymium", 144.24, 6, 6, "f", ElementCategory.Lanthanide, "[Xe] 4f⁴ 6s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• قوی‌ترین آهنرباهای دائم جهان (NdFeB) در توربین‌های بادی، بلندگوها و موتورهای خودروهای برقی مدرن."),
        Element(61, "Pm", "پرومتیم", "Promethium", 145.0, 6, 7, "f", ElementCategory.Lanthanide, "[Xe] 4f⁵ 6s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• تنها لانتانید رادیواکتیو فاقد ایزوتوپ پایدار؛ باتری‌های اتمی حسگرهای فضایی."),
        Element(62, "Sm", "ساماریم", "Samarium", 150.36, 6, 8, "f", ElementCategory.Lanthanide, "[Xe] 4f⁶ 6s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• آهنرباهای مقاوم به دمای بالا و داروی درمان دردهای سرطانی استخوان."),
        Element(63, "Eu", "اروپیم", "Europium", 151.96, 6, 9, "f", ElementCategory.Lanthanide, "[Xe] 4f⁷ 6s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• فسفرهای فلورسنت قرمز و آبی در اسکناس‌های یورو و مانیتورها جهت جلوگیری از جعل."),
        Element(64, "Gd", "گادولینیم", "Gadolinium", 157.25, 6, 10, "f", ElementCategory.Lanthanide, "[Xe] 4f⁷ 5d¹ 6s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• ماده حاجب مغناطیسی تزریقی در اسکن‌های MRI جهت تصویربرداری دقیق تومورها."),
        Element(65, "Tb", "تربیم", "Terbium", 158.93, 6, 11, "f", ElementCategory.Lanthanide, "[Xe] 4f⁹ 6s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• فسفرهای سبز در لامپ‌های کم‌مصرف و نمایشگرهای دیجیتال."),
        Element(66, "Dy", "دیسپروزیم", "Dysprosium", 162.5, 6, 12, "f", ElementCategory.Lanthanide, "[Xe] 4f¹⁰ 6s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• افزایش مقاومت آهنرباهای توربین‌های بادی در برابر دمای بالا."),
        Element(67, "Ho", "هولمیم", "Holmium", 164.93, 6, 13, "f", ElementCategory.Lanthanide, "[Xe] 4f¹¹ 6s²", null, null, null, null, ElementState.Solid, 3, "", "نکات طلایی کنکور:\n• بالاترین گشتاور مغناطیسی در بین عناصر؛ در لیزرهای جراحی پزشکی و سنگ‌شکنی کلیه."),
        Element(68, "Er", "اربیم", "Erbium", 167.26, 6, 14, "f", ElementCategory.Lanthanide, "[Xe] 4f¹² 6s²", null, null, null, null, ElementState.Solid, 4, "", "نکات طلایی کنکور:\n• تقویت‌کننده سیگنال در کابل‌های فیبر نوری بین‌قاره‌ای اقیانوس‌ها."),
        Element(69, "Tm", "تولیم", "Thulium", 168.93, 6, 15, "f", ElementCategory.Lanthanide, "[Xe] 4f¹³ 6s²", null, null, null, null, ElementState.Solid, 5, "", "نکات طلایی کنکور:\n• دستگاه‌های پرتابل اشعه X بدون نیاز به برق در مناطق محروم."),
