        Element(71, "Lu", "لوتتیم", "Lutetium", 174.97, 6, 17, "f", ElementCategory.Lanthanide, "[Xe] 4f¹⁴ 5d¹ 6s²", null, null, null, null, ElementState.Solid, 7, "", "نکات طلایی کنکور:\n• پایان سری لانتانیدها؛ سخت‌ترین و چگال‌ترین لانتانید؛ در اسکنرهای توموگرافی انتشار پوزیترون (PET)."),
        Element(72, "Hf", "هافنیم", "Hafnium", 178.49, 6, 4, "d", ElementCategory.TransitionMetal, "[Xe] 4f¹⁴ 5d² 6s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• میله‌های کنترل جذب نوترون در زیردریایی‌های اتمی و عایق دی‌الکتریک ترانزیستورهای پردازنده."),
        Element(73, "Ta", "تانتال", "Tantalum", 180.95, 6, 5, "d", ElementCategory.TransitionMetal, "[Xe] 4f¹⁴ 5d³ 6s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• مقاومت بی‌نظیر در برابر اسیدهای غلیظ؛ خازن‌های بسیار فشرده تانتالی در بردهای موبایل."),
        Element(74, "W", "تنگستن", "Tungsten", 183.84, 6, 6, "d", ElementCategory.TransitionMetal, "[Xe] 4f¹⁴ 5d⁴ 6s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• بالاترین نقطه ذوب در بین تمام فلزات جهان (۳۴۲۲ درجه سانتی‌گراد)!\n• رشته لامپ‌های التهابی؛ نوک مته‌های سنگین الماسه (کاربید تنگستن)."),
        Element(75, "Re", "رنیم", "Rhenium", 186.21, 6, 7, "d", ElementCategory.TransitionMetal, "[Xe] 4f¹⁴ 5d⁵ 6s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• از کمیاب‌ترین و گران‌ترین فلزات؛ آلیاژ پره‌های توربین موتور جت‌های مافوق صوت در دماهای بسیار بالا."),
        Element(76, "Os", "اسمیم", "Osmium", 190.23, 6, 8, "d", ElementCategory.TransitionMetal, "[Xe] 4f¹⁴ 5d⁶ 6s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• چگال‌ترین ماده طبیعی در کره زمین (چگالی ۲۲.۵۹ g/cm³)؛ نوک خودنویس‌های لوکس و سوزن گرامافون."),
        Element(77, "Ir", "ایریدیم", "Iridium", 192.22, 6, 9, "d", ElementCategory.TransitionMetal, "[Xe] 4f¹⁴ 5d⁷ 6s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• دومین عنصر چگال جهان و مقاوم‌ترین فلز به خوردگی شیمیایی؛ لایه مرزی رسوبات انقراض دایناسورها؛ شمع موتور خودروهای مسابقه‌ای."),
        Element(78, "Pt", "پلاتین", "Platinum", 195.08, 6, 10, "d", ElementCategory.TransitionMetal, "[Xe] 4f¹⁴ 5d⁹ 6s¹", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• فلز نجیب بسیار پایدار؛ کاتالیزور بی‌بدیل در مبدل‌های کاتالیستی، هیدروژناسیون و پیل‌های سوختی؛ داروی ضدسرطان شیمی‌درمانی سیس‌پلاتین."),
        Element(79, "Au", "طلا", "Gold", 196.97, 6, 11, "d", ElementCategory.TransitionMetal, "[Xe] 4f¹⁴ 5d¹⁰ 6s¹", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• استثنای آرایش: [Xe] 4f¹⁴ 5d¹⁰ 6s¹؛ چکش‌خوارترین و شکل‌پذیرترین فلز؛ تنها در تیزاب سلطانی (مخلوط ۳ به ۱ HCl و HNO₃) حل می‌شود؛ پتانسیل کاهش بسیار مثبت (+1.50 V)."),
        Element(80, "Hg", "جیوه", "Mercury", 200.59, 6, 12, "d", ElementCategory.TransitionMetal, "[Xe] 4f¹⁴ 5d¹⁰ 6s²", null, null, null, null, ElementState.Liquid, 1, "", "نکات طلایی کنکور:\n• تنها فلز مایع در دمای ۲۵ درجه؛ چگالی بالا ۱۳.۶؛ دماسنج‌ها، بارومترها و ملغمه‌های دندانی (آمالگام نقره-جیوه)؛ سمیت شدید بر سیستم عصبی مرکزی."),
        Element(81, "Tl", "تالیم", "Thallium", 204.38, 6, 13, "p", ElementCategory.PostTransitionMetal, "[Xe] 4f¹⁴ 5d¹⁰ 6s² 6p¹", null, null, null, null, ElementState.Solid, 3, "", "نکات طلایی کنکور:\n• فلز بسیار سمّی (سم بی‌بو و بی‌رنگ در گذشته)؛ در تصویربرداری خون‌رسانی قلب."),
