        Element(83, "Bi", "بیسموت", "Bismuth", 208.98, 6, 15, "p", ElementCategory.PostTransitionMetal, "[Xe] 4f¹⁴ 5d¹⁰ 6s² 6p³", null, null, null, null, ElementState.Solid, 5, "", "نکات طلایی کنکور:\n• سنگین‌ترین عنصری که عملاً پایدار محسوب می‌شود؛ آلیاژهای زودگداز آتش‌نشانی و داروی بیسموت ساب‌سیترات درمان زخم معده."),
