        Element(85, "At", "استاتین", "Astatine", 210.0, 6, 17, "p", ElementCategory.Halogen, "[Xe] 4f¹⁴ 5d¹⁰ 6s² 6p⁵", null, null, null, null, ElementState.Solid, 7, "", "نکات طلایی کنکور:\n• کمیاب‌ترین عنصر طبیعی پوسته زمین؛ هالوژن پرتوزا؛ پرتودرمانی هدفمند تومورهای سرطانی."),
        Element(86, "Rn", "رادون", "Radon", 222.0, 6, 18, "p", ElementCategory.NobleGas, "[Xe] 4f¹⁴ 5d¹⁰ 6s² 6p⁶", null, null, null, null, ElementState.Gas, 8, "", "نکات طلایی کنکور:\n• گاز نجیب رادیواکتیو ناشی از واپاشی اورانیم خاک و مصالح ساختمانی؛ ورود به زیرزمین‌ها و دومین عامل اصلی سرطان ریه بعد از دخانیات."),
        Element(87, "Fr", "فرانسیم", "Francium", 223.0, 7, 1, "s", ElementCategory.AlkaliMetal, "[Rn] 7s¹", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• ناپایدارترین و کمیاب‌ترین فلز قلیایی با نیمه‌عمر تنها ۲۲ دقیقه."),
        Element(88, "Ra", "رادیم", "Radium", 226.0, 7, 2, "s", ElementCategory.AlkalineEarth, "[Rn] 7s²", null, null, null, null, ElementState.Solid, 2, "", "نکات طلایی کنکور:\n• کشف شده توسط ماری کوری؛ تابش شدید پرتوهای آلفا، بتا و گاما؛ کاربرد تاریخی در رنگ‌های شب‌تاب عقربه ساعت‌ها."),
        Element(89, "Ac", "آکتینیم", "Actinium", 227.0, 7, 3, "f", ElementCategory.Actinide, "[Rn] 6d¹ 7s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• سرگروه آکتینیدها؛ چشمه نوترون و پرتودرمانی سلول‌های بنیادی سرطانی."),
        Element(90, "Th", "توریم", "Thorium", 232.04, 7, 4, "f", ElementCategory.Actinide, "[Rn] 6d² 7s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• سوخت آینده پاک نیروگاه‌های هسته‌ای با ایمنی بسیار بالاتر و پسماند کمتر از اورانیم."),
        Element(91, "Pa", "پروتاکتینیم", "Protactinium", 231.04, 7, 5, "f", ElementCategory.Actinide, "[Rn] 5f² 6d¹ 7s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• عنصر واسط در زنجیره واپاشی رادیواکتیو اورانیم در زمین‌شناسی."),
        Element(92, "U", "اورانیم", "Uranium", 238.03, 7, 6, "f", ElementCategory.Actinide, "[Rn] 5f³ 6d¹ 7s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• سوخت اصلی شکافت هسته‌ای در راکتورهای اتمی و نیروگاه‌های برق هسته‌ای (ایزوتوپ شکافت‌پذیر U-235)؛ غنی‌سازی صنعتی با تبدیل به گاز UF₆ و استفاده از سانتریفیوژهای گازی."),
        Element(93, "Np", "نپتونیم", "Neptunium", 237.0, 7, 7, "f", ElementCategory.Actinide, "[Rn] 5f⁴ 6d¹ 7s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• نخستین عنصر فرااورانیم؛ آشکارسازهای نوترون در رآکتورها."),
