        Element(95, "Am", "امریسیم", "Americium", 243.0, 7, 9, "f", ElementCategory.Actinide, "[Rn] 5f⁷ 7s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• عنصر ساخته دست بشر در حسگرهای حساس هشدار دود خانگی و ایمنی در برابر آتش‌سوزی."),
        Element(96, "Cm", "کوریم", "Curium", 247.0, 7, 10, "f", ElementCategory.Actinide, "[Rn] 5f⁷ 6d¹ 7s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• نام‌گذاری به افتخار پیر و ماری کوری؛ چشمه پرتوهای آلفا در کاوشگرهای خاک مریخ."),
        Element(97, "Bk", "برکلیم", "Berkelium", 247.0, 7, 11, "f", ElementCategory.Actinide, "[Rn] 5f⁹ 7s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• سنتز شده در دانشگاه برکلی؛ در تحقیقات بنیادی سنتز عناصر سنگین‌تر."),
        Element(98, "Cf", "کالیفرنیم", "Californium", 251.0, 7, 12, "f", ElementCategory.Actinide, "[Rn] 5f¹⁰ 7s²", null, null, null, null, ElementState.Solid, 1, "", "نکات طلایی کنکور:\n• چشمه بسیار فشرده و قدرتمند انتشار نوترون برای راه‌اندازی رآکتورهای اتمی و تشخیص عیوب بال هواپیماها."),
        Element(99, "Es", "اینشتینیم", "Einsteinium", 252.0, 7, 13, "f", ElementCategory.Actinide, "[Rn] 5f¹¹ 7s²", null, null, null, null, ElementState.Synthetic, 3, "", "نکات طلایی کنکور:\n• کشف شده در بقایای انفجار نخستین بمب هیدروژنی به نام آلبرت اینشتین."),
        Element(100, "Fm", "فرمیم", "Fermium", 257.0, 7, 14, "f", ElementCategory.Actinide, "[Rn] 5f¹² 7s²", null, null, null, null, ElementState.Synthetic, 4, "", "نکات طلایی کنکور:\n• عنصر سنگین نام‌گذاری شده به افتخار انریکو فرمی پیشگام انرژی اتمی."),
        Element(101, "Md", "مندلیفیم", "Mendelevium", 258.0, 7, 15, "f", ElementCategory.Actinide, "[Rn] 5f¹³ 7s²", null, null, null, null, ElementState.Synthetic, 5, "", "نکات طلایی کنکور:\n• نام‌گذاری به پاس زحمات دمیتری مندلیف پایه‌گذار جدول تناوبی عناصر شیمیایی."),
        Element(102, "No", "نوبلیم", "Nobelium", 259.0, 7, 16, "f", ElementCategory.Actinide, "[Rn] 5f¹⁴ 7s²", null, null, null, null, ElementState.Synthetic, 6, "", "نکات طلایی کنکور:\n• نام‌گذاری به افتخار آلفرد نوبل مخترع دینامیت و بنیان‌گذار جایزه نوبل."),
        Element(103, "Lr", "لارنسیم", "Lawrencium", 262.0, 7, 17, "f", ElementCategory.Actinide, "[Rn] 5f¹⁴ 7s² 7p¹", null, null, null, null, ElementState.Synthetic, 7, "", "نکات طلایی کنکور:\n• پایان سری آکتینیدها؛ به نام ارنست لارنس مخترع شتاب‌دهنده ذرات سیکلوترون."),
        Element(104, "Rf", "رادرفوردیم", "Rutherfordium", 267.0, 7, 4, "d", ElementCategory.TransitionMetal, "[Rn] 5f¹⁴ 6d² 7s²", null, null, null, null, ElementState.Synthetic, 1, "", "نکات طلایی کنکور:\n• نخستین عنصر ترانس‌آکتینید دوره هفتم؛ به نام ارنست رادرفورد کاشف هسته اتم."),
        Element(105, "Db", "دوبنیم", "Dubnium", 268.0, 7, 5, "d", ElementCategory.TransitionMetal, "[Rn] 5f¹⁴ 6d³ 7s²", null, null, null, null, ElementState.Synthetic, 1, "", "نکات طلایی کنکور:\n• به نام موسسه تحقیقات هسته‌ای دوبنا در روسیه."),
        Element(106, "Sg", "سیبورگیم", "Seaborgium", 269.0, 7, 6, "d", ElementCategory.TransitionMetal, "[Rn] 5f¹⁴ 6d⁴ 7s²", null, null, null, null, ElementState.Synthetic, 1, "", "نکات طلایی کنکور:\n• تنها عنصری که در زمان حیات دانشمند به نام او (گلن سیبورگ کشف‌کننده آکتینیدها) نام‌گذاری شد."),
        Element(107, "Bh", "بوریم", "Bohrium", 270.0, 7, 7, "d", ElementCategory.TransitionMetal, "[Rn] 5f¹⁴ 6d⁵ 7s²", null, null, null, null, ElementState.Synthetic, 1, "", "نکات طلایی کنکور:\n• به نام نیلز بور دانشمند برجسته نظریه کوانتومی و مدل اتمی مدارها."),
